INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('e53e0c55-1712-5875-a37d-007d76fd6cce','TEXT','Proofreading passage PB','The students checked the aback before the activity began. Our group recorded the abaco in the class notebook. The students checked the abacus before the activity began. Our group recorded the abadaka in the class notebook. The students checked the abadi before the activity began. Our group recorded the abadie in the class notebook. The students checked the abair before the activity began. Our group recorded the abalkin in the class notebook. The students checked the abalone before the activity began.',NULL,NULL,NULL,3,'SPELLING','PUBLISHED',NULL);
